import{_ as t,o as a,c as n,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Explore citation connections","description":"","frontmatter":{},"headers":[],"relativePath":"guide/citation-map.md","filePath":"guide/citation-map.md","lastUpdated":1793111003000}'),i={name:"guide/citation-map.md"};function r(s,e,p,c,d,h){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="explore-citation-connections" tabindex="-1">Explore citation connections <a class="header-anchor" href="#explore-citation-connections" aria-label="Permalink to &quot;Explore citation connections&quot;">​</a></h1><p>See the research neighborhood around a search, rather than isolated papers.</p><h2 id="get-a-map" tabindex="-1">Get a map <a class="header-anchor" href="#get-a-map" aria-label="Permalink to &quot;Get a map&quot;">​</a></h2><p>Choose <strong>OpenAlex</strong> and enable citation expansion before searching. References and citing papers are explored within the chosen budget.</p><p>Open <strong>Citation evidence</strong> from the results, or <strong>Reviews → Citation evidence → Paper relations</strong>. An empty map is expected when no citation data was collected; changing tabs does not retroactively run expansion.</p><h2 id="read-the-graph" tabindex="-1">Read the graph <a class="header-anchor" href="#read-the-graph" aria-label="Permalink to &quot;Read the graph&quot;">​</a></h2><p>Nodes represent papers. Arrows point from the citing paper to the cited paper.</p><p>The legend distinguishes result, seed, and forward/backward expansion roles. These describe how a paper entered the graph, not its quality.</p><p>Select a node to inspect its paper and available source link. Adjust the view with graph controls when the network is dense.</p><h2 id="understand-the-limits" tabindex="-1">Understand the limits <a class="header-anchor" href="#understand-the-limits" aria-label="Permalink to &quot;Understand the limits&quot;">​</a></h2><p>This is a bounded exploration, not a complete field-wide citation network. Source coverage, missing identifiers, and updates affect the connections.</p><p>Citation counts are not relevance scores: a recent paper may be relevant with few citations.</p><p>Return to <a href="./results">Results</a> to read, select, or export.</p>',13)])])}const m=t(i,[["render",r]]);export{u as __pageData,m as default};
